INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(123111, 'ruRU', '', 'У меня нет друзей... ну, кроме тебя, Галиндре.', 24330),
(123116, 'ruRU', '', 'Mrgrlglrllrr.', 24330),
(123118, 'ruRU', '', 'Grrmgmrlgmrrm.', 24330),
(123120, 'ruRU', '', 'Mgrmglrm.', 24330),
(123122, 'ruRU', '', 'Mlgrmgrlmgrmrrrmgrrr.', 24330),
(123123, 'ruRU', '', 'Mrrmgmrlgmm.', 24330),
(123124, 'ruRU', '', 'Grlmgmmrr!', 24330),
(123144, 'ruRU', '', 'Используй Ярость шамана!', 24330),
(123146, 'ruRU', '', 'Фарондис виновен в нашем проклятии... он дорого за это заплатит!', 24330),
(123147, 'ruRU', '', 'С Фарондисом никогда не будет мира, пока мы прокляты!', 24330),
(123194, 'ruRU', '', 'Используй Вызов питомца, чтобы призвать своего питомца в бой.', 24330),
(123195, 'ruRU', '', 'Вместе со своим верным питомцем ты хозяин своего окружения. Вызов питомца призовёт твоего питомца к тебе.', 24330),
(123200, 'ruRU', '', 'Используй Рассечение, чтобы расправиться со всеми врагами.', 24330),
(123201, 'ruRU', '', 'Рассечение проводит твоё оружие перед тобой, нанося урон всем целям на его пути.', 24330),
(123202, 'ruRU', '', 'Иногда ты окажешься в численном меньшинстве. Не волнуйся, ты можешь обрушить разрушение на целую орду противников одновременно!', 24330),
(123203, 'ruRU', '', 'Охотники выживания процветают в ближнем бою, где они используют комбинацию инструментов, чтобы жестоко сокрушить свою жертву.', 24330),
(123204, 'ruRU', '', 'Охотники выживания процветают в ближнем бою, где они используют комбинацию инструментов, чтобы жестоко сокрушить свою жертву.', 24330),
(123205, 'ruRU', '', 'Используй Укус мангуста!', 24330),
(123206, 'ruRU', '', 'Используй Иссечение!', 24330),
(123207, 'ruRU', '', 'Используй Гарпун!', 24330),
(123208, 'ruRU', '', 'Используй Фланговый удар!', 24330),
(123209, 'ruRU', '', 'Используй Притворную смерть, чтобы спастись!', 24330),
(123210, 'ruRU', '', 'Используй Рассечение, чтобы нанести урон нескольким врагам одновременно!', 24330),
(123211, 'ruRU', '', 'Используй Укус мангуста на тренировочном манекене.', 24330),
(123212, 'ruRU', '', 'Накопи заряды Укуса мангуста, затем высвободи их все сразу для максимального эффекта.', 24330),
(123213, 'ruRU', '', 'Укус мангуста — атака, что становится мощнее каждый раз, когда ты её используешь.', 24330),
(123214, 'ruRU', '', 'Твоя самая мощная тактика — заставить противника пошатнуться, а затем стабильно увеличивать урон, пока он не будет побеждён.', 24330),
(123215, 'ruRU', '', 'Используй Фланговый удар на тренировочном манекене.', 24330),
(123217, 'ruRU', '', 'Фланговый удар — скоординированная атака между тобой и твоим питомцем, что может нанести калечащий урон.', 24330),
(123218, 'ruRU', '', 'Время навалиться на цель вдвоём!', 24330),
(123219, 'ruRU', '', 'Помни об использовании Иссечения каждый раз, когда цель не поражена им.', 24330),
(123220, 'ruRU', '', 'Используй Иссечение на тренировочном манекене.', 24330),
(123221, 'ruRU', '', 'Иссечение заставит твою цель кровоточить, нанося урон с течением времени.', 24330),
(123222, 'ruRU', '', 'Теперь, когда ты сократил расстояние до своей жертвы, время изнурить её раной, от которой ей будет трудно восстановиться.', 24330),
(123223, 'ruRU', '', 'Используй Гарпун против тренировочного манекена.', 24330),
(123224, 'ruRU', '', 'Используя способность Гарпун, ты можешь зацепить врага и метнуться к нему.', 24330),
(123225, 'ruRU', '', 'Твои враги обнаружат, что, попав в твой прицел, у них мало шансов спастись.', 24330),
(123226, 'ruRU', '', 'Хочешь услышать сказание из прошлого, $n?', 24330),
(123233, 'ruRU', '', 'Это действительно просто. Подойди к кубу и взаимодействуй с ним, чтобы начать раунд его игры. Просто следуй по пути, что он показывает, прежде чем заполнить всю сетку, и ты засчитаешь раунд. Набери достаточно раундов, и куб должен активироваться для тебя.', 24330),
(123234, 'ruRU', '', 'Садись на одного из моих мана-саблезубов и направляй его через высокие узлы лей-энергии, что ты видишь вокруг. Проведи его через достаточное количество лей-энергии, чтобы полностью зарядить, и дело сделано! Помни, мана-саблезуб отлично разгоняется по прямой, но замедляется на поворотах. Старайся минимизировать количество корректировок направления.', 24330);
